import { Component, OnInit, OnDestroy } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { GovBrInputModule, GovBrSelectModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { BaseDeCalculoService } from '../../../services/base-de-calculo.service';
import { BarraBotoesComponent } from '../../diversos/barra-botoes/barra-botoes.component';
import { MensagemService } from '../../../services/mensagem.service';

@Component({
  selector: 'simulador-base-calculo-cbs-ibs-bens',
  templateUrl: './simulador-base-calculo-cbs-ibs-bens.component.html',
  styleUrl: './simulador-base-calculo-cbs-ibs-bens.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrInputModule,
    GovBrSelectModule,
    TooltipModule,
    BarraBotoesComponent
  ]
})
export class SimuladorBaseCalculoCbsIbsBensComponent implements OnInit, OnDestroy {

  private readonly MIN_YEAR = 2026;
  private readonly YEAR_LIMIT_PIS_COFINS = 2026;
  private readonly YEAR_LIMIT_ISS_ICMS = 2032;

  public form!: FormGroup;

  response: any = null;
  yearValues: any[] = [];
  
  tooltipISS: string = 'Para hipótese de nota conjugada: mercadoria e serviço no mesmo documento.';

  constructor(
    private readonly baseDeCalculoService: BaseDeCalculoService,
    private readonly formBuilder: FormBuilder,
    private mensagemService: MensagemService
  ) { }


  ngOnDestroy(): void {

  }

  ngOnInit(): void {

    this.yearValues = this.generateYearValues();
    const currentYear = new Date().getFullYear();
    const effectiveYear = Math.max(currentYear, this.MIN_YEAR);
    const defaultYear = this.yearValues.find(y => y.value === effectiveYear);

    this.form = this.formBuilder.group({

      anoFatoGeradorControl: [defaultYear, [Validators.required]],

      valorBemControl: [0.0, [Validators.required]],
      ajusteAcrescimosControl: [0.0, [Validators.required]],
      jurosControl: [0.0, [Validators.required]],
      multasControl: [0.0, [Validators.required]],
      encargosControl: [0.0, [Validators.required]],
      freteControl: [0.0, [Validators.required]],
      impostoSeletivoControl: [0.0, [Validators.required]],
      outrosTributosControl: [0.0, [Validators.required]],
      demaisImportanciasControl: [0.0, [Validators.required]],

      icmsControl: [0.0, [Validators.required]],
      issControl: [0.0, [Validators.required]],
      pisControl: [0.0, [Validators.required]],
      pisImportacaoControl: [0.0, [Validators.required]],
      cofinsControl: [0.0, [Validators.required]],
      cofinsImportacaoControl: [0.0, [Validators.required]],
      cosipControl: [0.0, [Validators.required]],
      ipiControl: [0.0, [Validators.required]],
      descontoIncondicionalControl: [0.0, [Validators.required]],

      valorBaseCalculoControl: [0, [Validators.required]],
    });

    this.form.valueChanges.subscribe((value) => {
      this.resetarValores();
    });

  }

  resetarValores() {
    this.response = null;
  }

  limpar = () => {
    const currentYear = new Date().getFullYear();
    const effectiveYear = Math.max(currentYear, this.MIN_YEAR);
    const defaultYear = this.yearValues.find(y => y.value === effectiveYear);
    
    this.form.reset({
      anoFatoGeradorControl: defaultYear,
      valorBemControl: 0.0,
      ajusteAcrescimosControl: 0.0,
      jurosControl: 0.0,
      multasControl: 0.0,
      encargosControl: 0.0,
      freteControl: 0.0,
      impostoSeletivoControl: 0.0,
      outrosTributosControl: 0.0,
      demaisImportanciasControl: 0.0,
      icmsControl: 0.0,
      issControl: 0.0,
      pisControl: 0.0,
      pisImportacaoControl: 0.0,
      cofinsControl: 0.0,
      cofinsImportacaoControl: 0.0,
      cosipControl: 0.0,
      ipiControl: 0.0,
      descontoIncondicionalControl: 0.0,
      valorBaseCalculoControl: 0,
    });
    this.resetarValores();
  }

  submit(event: any) {

    if (!this.form.valid) {
      this.mensagemService.mostrar('Erro', 'Erro', 'Formulário inválido.');
      return;
    }

    const body: any = {
      anoFatoGerador: this.form.controls["anoFatoGeradorControl"].value?.value,
      valorBem: this.form.controls["valorBemControl"].value,
      ajusteAcrescimos: this.form.controls["ajusteAcrescimosControl"].value,
      juros: this.form.controls["jurosControl"].value,
      multas: this.form.controls["multasControl"].value,
      encargos: this.form.controls["encargosControl"].value,
      frete: this.form.controls["freteControl"].value,
      impostoSeletivo: this.form.controls["impostoSeletivoControl"].value,
      outrosTributos: this.form.controls["outrosTributosControl"].value,
      demaisImportancias: this.form.controls["demaisImportanciasControl"].value,
      icms: this.form.controls["icmsControl"].value,
      cosip: this.form.controls["cosipControl"].value,
      ipi: this.form.controls["ipiControl"].value,
      descontoIncondicional: this.form.controls["descontoIncondicionalControl"].value,
    };

    if (!this.isAnoApos2032()) {
      body.iss = this.form.controls["issControl"].value;
    }

    if (!this.isAnoApos2026()) {
      body.pis = this.form.controls["pisControl"].value;
      body.pisImportacao = this.form.controls["pisImportacaoControl"].value;
      body.cofins = this.form.controls["cofinsControl"].value;
      body.cofinsImportacao = this.form.controls["cofinsImportacaoControl"].value;
    }

    this.baseDeCalculoService.aferirBaseDeCalculoCIBS(body).subscribe({
      next: data => {
        this.response = data;
      },
      error: error => {

      }
    });

  }

  controlChange(event: any) {

  }

  isAnoApos2026(): boolean {
    const ano = this.form.controls["anoFatoGeradorControl"].value?.value;
    if (!ano) return false;
    return ano > this.YEAR_LIMIT_PIS_COFINS;
  }

  isAnoApos2032(): boolean {
    const ano = this.form.controls["anoFatoGeradorControl"].value?.value;
    if (!ano) return false;
    return ano > this.YEAR_LIMIT_ISS_ICMS;
  }

  private generateYearValues(): any[] {
    const years = [];
    for (let year = this.MIN_YEAR; year <= 2100; year++) {
      years.push({ value: year, label: year.toString() });
    }
    return years;
  }

}
