import { HttpClient } from "@angular/common/http";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { environment } from "../../environments/environment";

@Injectable({
    providedIn: 'root'
})
export class BaseDeCalculoService {
    
    private baseUrl = environment.APIEndpoint;
    constructor(private http: HttpClient) {}

    aferirBaseDeCalculoISMercadorias(body: any): Observable<any> {
            return this.http.post<any>(`${this.baseUrl}/calculadora/base-calculo/is-mercadorias`, body);
    }

    aferirBaseDeCalculoCIBS(body: any): Observable<any> {
        return this.http.post<any>(`${this.baseUrl}/calculadora/base-calculo/cbs-ibs-mercadorias`, body);
    }
    
    aferirBaseDeCalculoCIBSTransicao(body: any): Observable<any> {
        return this.http.post<any>(`${this.baseUrl}/calculadora/nfse/base-calculo`, body);
    }

}
